//! Money-relevance ranking in context (`docs/specs/opponent-engine.md`,
//! section 7.2), proved on simulated villains: the fixed-seed cash 6-max and
//! MTT 9-max knockout corpora of `sim_matrix_tests`, generated by
//! `scripts/sim/generate.mjs` into a temporary folder and imported into a
//! temporary database. Each villain is replayed once; only the between-hands
//! context handed to `EngineCache::payload` changes between two checks
//! (seat, stack depth, stage, bounty, Zoom), so every change of the top
//! reads comes from the ranking alone.
//!
//! The ranking is only shown in the `strategic-analysis` build, so these
//! tests run there.
#![cfg(feature = "strategic-analysis")]

use std::path::{Path, PathBuf};
use std::process::Command;

use rusqlite::Connection;
use serde_json::Value;
use velora_poker_lib::db;
use velora_poker_lib::description_rules::{ConfidenceTier, RuleCategory};
use velora_poker_lib::engine::rank::{
    context_multiplier, score, DEEP_ALL_IN, DEEP_POSTFLOP, EARLY_STAGE_LIMP, LATE_STAGE_PRIORITY, RESHOVE_PRIORITY,
    SEAT_DIRECT, SEAT_OTHER_SIDE_DIRECT, STANDARD_ALL_IN,
};
use velora_poker_lib::engine::rules::{
    DEPTH_OPPOSITES, H2H_OPPOSITES, POSTFLOP_OPPOSITES, PREFLOP_OPPOSITES, REFINED_OPPOSITES, SHOWDOWN_OPPOSITES,
    TOURNAMENT_OPPOSITES,
};
use velora_poker_lib::engine::{
    load_hand, rank, rank_reads, rule_def, villain_context, BountyContext, EngineCache, EngineContext,
    EnginePayload, EngineRuleResult, Family, SeatRelation, Side, StackBucket, Stage, TagSource,
};
use velora_poker_lib::import::import_directory;

// ------------------------------------------------------------------ corpora

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().expect("repo root").to_path_buf()
}

fn profiles() -> Value {
    let text = std::fs::read_to_string(repo_root().join("scripts/sim/profiles.json")).expect("read profiles.json");
    serde_json::from_str(&text).expect("profiles.json is JSON")
}

/// The baseline profiles (those without engine stat targets), comma-separated
/// for `--profiles`: the read profiles play their own corpora
/// (`sim_convergence_tests`, `sim_formats_tests`), so these corpora stay the
/// ones the expectations below were written on.
fn baseline_ids() -> String {
    let profiles = profiles();
    let ids: Vec<&str> = profiles["profiles"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|p| p.get("engineTargets").is_none())
        .map(|p| p["id"].as_str().unwrap())
        .collect();
    ids.join(",")
}

/// `path` resolves inside `root`.
fn inside(root: &Path, path: &Path) -> bool {
    let root = std::fs::canonicalize(root).expect("canonical temp root");
    std::fs::canonicalize(path).is_ok_and(|p| p.starts_with(&root))
}

/// Generates the `sim_matrix_tests` corpus of `format` under `root` and
/// imports it into a temporary database there.
fn corpus(root: &Path, format: &str) -> Connection {
    let (seed, tables, hands) = match format {
        "cash" => ("matrix-cash", 6, 600),
        "mtt" => ("matrix-mtt", 4, 400),
        other => panic!("no corpus for {other}"),
    };
    if let Some(appdata) = std::env::var_os("APPDATA") {
        let real = PathBuf::from(appdata).join("com.velora.poker");
        assert!(!root.starts_with(&real), "the temporary folder is inside the real Velora data folder");
    }
    let out = root.join(format).join("HandHistory");
    let output = Command::new("node")
        .current_dir(repo_root())
        .arg("scripts/sim/generate.mjs")
        .args(["--out", out.to_str().expect("utf-8 path"), "--format", format, "--seed", seed])
        .args(["--tables", &tables.to_string(), "--hands", &hands.to_string(), "--pace", "0", "--manifest"])
        .args(["--profiles", &baseline_ids()])
        .output()
        .expect("run node scripts/sim/generate.mjs (is node on PATH?)");
    assert!(output.status.success(), "generator failed: {}", String::from_utf8_lossy(&output.stderr));
    assert!(inside(root, &out), "hand histories outside the temporary folder");
    let db_path = root.join(format).join("velora.db");
    let mut conn = db::open(&db_path).expect("open temp db");
    conn.execute_batch("PRAGMA synchronous = OFF;").expect("pragma");
    assert!(inside(root, &db_path), "database outside the temporary folder");
    let summary = import_directory(&mut conn, &out).expect("import directory");
    assert_eq!(summary.hands_failed + summary.hands_rejected_invalid, 0, "{format}: import failures");
    conn
}

/// A simulated villain: his id and the between-hands context of his latest
/// hand (format, variant and source hand stay his real ones).
fn villain(conn: &Connection, name: &str) -> (i64, EngineContext) {
    let pid: i64 = conn
        .query_row("SELECT id FROM players WHERE name = ?1", [name], |row| row.get(0))
        .unwrap_or_else(|_| panic!("{name} is not in the corpus"));
    let ids: Vec<i64> = conn
        .prepare(
            "SELECT h.id FROM hands h JOIN player_hands p ON p.hand_id = h.id
              WHERE p.player_id = ?1 ORDER BY h.played_at DESC, h.id DESC",
        )
        .unwrap()
        .query_map([pid], |row| row.get(0))
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap();
    let context = ids
        .iter()
        .find_map(|id| villain_context(&load_hand(conn, *id).unwrap()?, pid))
        .unwrap_or_else(|| panic!("{name} has no context"));
    (pid, context)
}

/// Every simulated villain of `profiles.json` in the corpus.
fn villains(conn: &Connection) -> Vec<(String, i64, EngineContext)> {
    let mut all = Vec::new();
    for profile in profiles()["profiles"].as_array().expect("profiles") {
        for name in profile["players"].as_array().expect("players") {
            let name = name.as_str().unwrap();
            let present: bool = conn
                .query_row("SELECT EXISTS(SELECT 1 FROM players WHERE name = ?1)", [name], |row| row.get(0))
                .unwrap();
            if present {
                let (pid, ctx) = villain(conn, name);
                all.push((name.to_string(), pid, ctx));
            }
        }
    }
    assert!(all.len() >= 10, "simulated villains in the corpus: {}", all.len());
    all
}

// ------------------------------------------------------------------ contexts

/// `base` at `eff` big blinds effective, with no seat, stage or bounty: each
/// check adds back only the factor it is about.
fn at(base: &EngineContext, eff: f64) -> EngineContext {
    EngineContext {
        effective_stack_bb: Some(eff),
        stack_bucket: Some(StackBucket::of(eff)),
        stage: None,
        bounty: None,
        seat: None,
        ..base.clone()
    }
}

/// `distance` occupied seats clockwise from the hero at an `n`-handed table
/// (section 5).
fn seat(distance: u32, n: u32) -> SeatRelation {
    let side = if f64::from(distance) <= (f64::from(n) - 1.0) / 2.0 { Side::Left } else { Side::Right };
    SeatRelation {
        distance,
        side,
        acts_after_hero: side == Side::Left,
        direct_left: distance == 1,
        direct_right: distance == n - 1,
    }
}

fn seated(mut ctx: EngineContext, distance: u32, n: u32) -> EngineContext {
    ctx.seat = Some(seat(distance, n));
    ctx
}

fn staged(mut ctx: EngineContext, stage: Stage) -> EngineContext {
    ctx.stage = Some(stage);
    ctx
}

fn bounty(mut ctx: EngineContext, ratio: f64, hero_covers: bool) -> EngineContext {
    ctx.bounty = Some(BountyContext { amount: 5.0 * ratio, currency: Some("USD".into()), ratio: Some(ratio), hero_covers: Some(hero_covers) });
    ctx
}

// ------------------------------------------------------------------ reads

fn payload(cache: &mut EngineCache, conn: &Connection, pid: i64, ctx: &EngineContext) -> EnginePayload {
    cache.payload(conn, pid, Some(ctx.clone())).expect("engine payload")
}

/// A fact of the latest hand rather than a read of the player (section 7).
fn is_fact(rule_id: &str) -> bool {
    rule_id.starts_with("ctx.") || rule_id == "ko.big_bounty"
}

/// The tendency reads in ranking order, facts left out.
fn tendency(p: &EnginePayload) -> Vec<&str> {
    p.reads.iter().map(|r| r.rule_id.as_str()).filter(|id| !is_fact(id)).collect()
}

fn listing(p: &EnginePayload) -> String {
    p.reads.iter().map(|r| format!("{} {:.2} (×{:.2})", r.rule_id, r.score, r.multiplier)).collect::<Vec<_>>().join(", ")
}

fn find<'a>(p: &'a EnginePayload, id: &str) -> &'a EngineRuleResult {
    p.reads.iter().find(|r| r.rule_id == id).unwrap_or_else(|| panic!("{id} missing: {}", listing(p)))
}

fn position(p: &EnginePayload, id: &str) -> usize {
    tendency(p).iter().position(|r| *r == id).unwrap_or_else(|| panic!("{id} missing: {}", listing(p)))
}

fn assert_top(label: &str, p: &EnginePayload, expected: &[&str]) {
    let top = tendency(p);
    assert!(top.len() >= expected.len() && top[..expected.len()] == *expected, "{label}: top reads {top:?}, expected {expected:?}\n{}", listing(p));
}

// ------------------------------------------------------------------ checks

/// Seat relation (section 7.2): directly on the hero's left, his answers to
/// the hero's opens (flats, 3-bets) move up; directly on the right, his own
/// opens lead. `left_leads`: the left read is his top read on the left;
/// otherwise it only climbs above the right read there (section 18: no MTT
/// villain of the corpus has reads close enough to flip on both sides).
/// `plain_top` leads without a seat (no table scope): the bigger read.
fn check_seat(
    conn: &Connection,
    cache: &mut EngineCache,
    name: &str,
    n: u32,
    (left_read, right_top): (&str, &str),
    left_leads: bool,
    plain_top: &str,
) {
    let (pid, base) = villain(conn, name);
    let plain = payload(cache, conn, pid, &at(&base, 100.0));
    let left = payload(cache, conn, pid, &seated(at(&base, 100.0), 1, n));
    let right = payload(cache, conn, pid, &seated(at(&base, 100.0), n - 1, n));
    if left_leads {
        assert_top(&format!("{name} directly on the left"), &left, &[left_read]);
    } else {
        assert!(position(&plain, right_top) < position(&plain, left_read), "{name} without a seat: {}", listing(&plain));
        assert!(position(&left, left_read) < position(&left, right_top), "{name} directly on the left: {}", listing(&left));
    }
    assert_top(&format!("{name} directly on the right"), &right, &[right_top]);
    assert_eq!(rule_def(left_read).seat, Some(Side::Left), "{left_read} is a left-side read");
    assert_eq!(rule_def(right_top).seat, Some(Side::Right), "{right_top} is a right-side read");
    assert_top(&format!("{name} without a seat"), &plain, &[plain_top]);
    // The factors are section 7.2's, and the advice says where he sits.
    let l = find(&left, left_read);
    assert!((l.multiplier - SEAT_DIRECT).abs() < 1e-12, "{}", listing(&left));
    assert!(l.advice.ends_with("(directly on your left)."), "{}", l.advice);
    let r = find(&left, right_top);
    assert!((r.multiplier - SEAT_OTHER_SIDE_DIRECT).abs() < 1e-12, "{}", listing(&left));
}

/// Zoom (section 5): the same seat, the same villain; at a Zoom table the
/// seat changes nothing, at a ring table directly on the hero's right it
/// moves his 4-bets of the hero's 3-bets to the top.
fn check_zoom(conn: &Connection, cache: &mut EngineCache) {
    let (pid, base) = villain(conn, "TwentyBigBlinds");
    let plain = payload(cache, conn, pid, &at(&base, 100.0));
    let mut zoom = seated(at(&base, 100.0), 5, 6);
    zoom.variant = Some("zoom_cash".into());
    let mut ring = zoom.clone();
    ring.variant = Some("cash".into());
    let zoom = payload(cache, conn, pid, &zoom);
    let ring = payload(cache, conn, pid, &ring);
    assert_top("Zoom, a seat directly on the right", &zoom, &["pf.3bet.high_ip"]);
    assert_top("ring table, the same seat", &ring, &["pf.4bet.high"]);
    assert_eq!(zoom.reads.len(), plain.reads.len());
    for (z, p) in zoom.reads.iter().zip(&plain.reads) {
        assert_eq!((z.rule_id.as_str(), z.score, z.advice.as_str()), (p.rule_id.as_str(), p.score, p.advice.as_str()), "Zoom ignores the seat");
        assert!(!z.adapted_by.contains(&"ctx.seat_relation"), "{}", z.rule_id);
    }
}

/// Stack depth (section 7.2) with only the effective stack changing:
/// all-in reads lead at 15bb or less (the only eligible ones) and rank
/// ×1.5 at 15–25bb, ×0.6/×0.5 at 60–150/150+; postflop reads rank ×1.2
/// above 150bb; at 15–25bb his reshove read replaces his 3-bet reads, at
/// 25–40bb it ranks ×1.25 above them, at 100bb his 3-bets lead.
fn check_depth(conn: &Connection, cache: &mut EngineCache) {
    // A LAG on the hero's right (four seats clockwise at six-max, the seat
    // he had in his latest hand).
    let (pid, base) = villain(conn, "SprayAndPray");
    let by = |cache: &mut EngineCache, eff| payload(cache, conn, pid, &seated(at(&base, eff), 4, 6));
    let push_fold = by(cache, 12.0);
    let reshove = by(cache, 20.0);
    let standard = by(cache, 100.0);
    let deep = by(cache, 200.0);
    assert_top("LAG at 12bb", &push_fold, &["stk.call_shove.wide"]);
    assert!(tendency(&push_fold).iter().all(|id| id.starts_with("stk.") || id.starts_with("sd.")), "{}", listing(&push_fold));
    assert_top("LAG at 20bb", &reshove, &["pf.rfi.loose_early", "stk.call_shove.wide"]);
    assert_top("LAG at 100bb", &standard, &["pf.rfi.loose_early", "post.river_bet.high"]);
    assert_top("LAG at 200bb", &deep, &["pf.rfi.loose_early", "post.river_bet.high"]);
    assert!((find(&reshove, "stk.call_shove.wide").multiplier - RESHOVE_PRIORITY).abs() < 1e-12);
    assert!((find(&standard, "stk.call_shove.wide").multiplier - STANDARD_ALL_IN).abs() < 1e-12);
    assert!((find(&deep, "stk.call_shove.wide").multiplier - DEEP_ALL_IN).abs() < 1e-12);
    assert!((find(&deep, "post.river_bet.high").multiplier - DEEP_POSTFLOP).abs() < 1e-12);
    // Above 150bb his probes pass his flats.
    assert!(position(&deep, "post.probe.high") < position(&deep, "pf.cold_call.high"));
    assert!(position(&standard, "post.probe.high") > position(&standard, "pf.cold_call.high"));

    // A 20bb reshover: his reshoves lead down to push/fold depth, his
    // 3-bets from 60bb up.
    let (pid, base) = villain(conn, "TwentyBigBlinds");
    let by = |cache: &mut EngineCache, eff| payload(cache, conn, pid, &at(&base, eff));
    let push_fold = by(cache, 12.0);
    let reshove = by(cache, 20.0);
    let jam = by(cache, 30.0);
    let standard = by(cache, 100.0);
    let deep = by(cache, 200.0);
    for (label, p) in [("12bb", &push_fold), ("20bb", &reshove), ("30bb", &jam)] {
        assert_top(&format!("reshover at {label}"), p, &["stk.reshove.high"]);
    }
    // Depth pair at 20bb and, for his reshove read, through jam depth
    // (section 18): his 3-bet sample is his jams.
    for (label, p) in [("20bb", &reshove), ("30bb", &jam)] {
        assert!(tendency(p).iter().all(|id| !id.starts_with("pf.3bet.")), "depth pair at {label}: {}", listing(p));
    }
    for (label, p) in [("100bb", &standard), ("200bb", &deep)] {
        assert_top(&format!("reshover at {label}"), p, &["pf.3bet.high_ip"]);
    }
    assert!(position(&standard, "stk.reshove.high") > position(&standard, "pf.3bet.high_ip"));
}

/// Tournament stage (section 7.2), effective stack 30bb: all-in and blind
/// battle reads rank ×1.25 late, limp reads ×1.25 early.
fn check_stage(conn: &Connection, cache: &mut EngineCache) {
    let (pid, base) = villain(conn, "FoldEquityFern");
    let early = payload(cache, conn, pid, &staged(at(&base, 30.0), Stage::Early));
    let late = payload(cache, conn, pid, &staged(at(&base, 30.0), Stage::Late));
    assert_top("nit, early stage", &early, &["pf.profile.nit"]);
    assert_top("nit, late stage", &late, &["stk.call_shove.tight"]);
    assert!((find(&late, "stk.call_shove.tight").multiplier - LATE_STAGE_PRIORITY).abs() < 1e-12);
    assert_eq!(find(&early, "stk.call_shove.tight").multiplier, 1.0);

    let (pid, base) = villain(conn, "CallMeMaybe77");
    let early = payload(cache, conn, pid, &staged(at(&base, 30.0), Stage::Early));
    assert_top("fish, early stage", &early, &["pf.cold_call.high", "stage.early.passive"]);
    assert!((find(&early, "stage.early.passive").multiplier - EARLY_STAGE_LIMP).abs() < 1e-12);

    let (pid, base) = villain(conn, "TripleBarrelTom");
    let middle = payload(cache, conn, pid, &staged(at(&base, 30.0), Stage::Middle));
    let late = payload(cache, conn, pid, &staged(at(&base, 30.0), Stage::Late));
    assert_eq!(find(&middle, "pf.steal.high").multiplier, 1.0);
    assert!((find(&late, "pf.steal.high").multiplier - LATE_STAGE_PRIORITY).abs() < 1e-12);
}

/// Bounties (section 7.2) at 25bb or less: when he covers the hero, his
/// calls of the hero's shoves lead (×1.25); when the hero covers a big
/// bounty, the hero's calls of his shoves and reshoves rank ×1.5, so his
/// reshoves lead; above 25bb the bounty changes nothing.
fn check_bounty(conn: &Connection, cache: &mut EngineCache) {
    // Two nits (section 18: GrindHouseGus has no call-vs-shove read on this
    // corpus after the section 18 engine fixes).
    let (pid, base) = villain(conn, "RockSolidRui");
    assert_top("RockSolidRui at 20bb, no bounty", &payload(cache, conn, pid, &at(&base, 20.0)), &["pf.rfi.tight_early"]);
    for (name, otherwise) in [("RockSolidRui", "stk.reshove.low"), ("FoldEquityFern", "stk.reshove.low")] {
        let (pid, base) = villain(conn, name);
        let covered = payload(cache, conn, pid, &bounty(at(&base, 20.0), 1.0, false));
        let covering = payload(cache, conn, pid, &bounty(at(&base, 20.0), 3.0, true));
        assert_top(&format!("{name} covers the hero at 20bb"), &covered, &["stk.call_shove.tight"]);
        assert_top(&format!("the hero covers {name} at 20bb"), &covering, &[otherwise]);
        let deeper = payload(cache, conn, pid, &bounty(at(&base, 30.0), 1.0, false));
        assert_eq!(find(&deeper, "stk.call_shove.tight").multiplier, 1.0, "no bounty factor above 25bb");
    }
    let (pid, base) = villain(conn, "TwentyBigBlinds");
    let big = payload(cache, conn, pid, &bounty(at(&base, 12.0), 3.0, true));
    let small = payload(cache, conn, pid, &bounty(at(&base, 12.0), 1.0, true));
    // His reshoves lead either way; the 3x bounty ranks them ×1.5 (section
    // 18: his open-shove read no longer fires on this corpus after the
    // section 18 engine fixes).
    assert_top("the hero covers his 3x bounty at 12bb", &big, &["stk.reshove.high", "sd.tell.big_is_value"]);
    assert_top("the hero covers his 1x bounty at 12bb", &small, &["stk.reshove.high", "sd.tell.big_is_value"]);
    let factor = find(&big, "stk.reshove.high").multiplier / find(&small, "stk.reshove.high").multiplier;
    assert!((factor - 1.5).abs() < 1e-12, "{}
{}", listing(&big), listing(&small));
}

/// The chip tag keeps section 7's precedence under the context ranking: a
/// tournament villain on 25bb or less shows his best all-in read (his stack
/// only without one), above it the top read's tag.
fn check_chip_tag(conn: &Connection, cache: &mut EngineCache) {
    let (pid, base) = villain(conn, "TwentyBigBlinds");
    let short = payload(cache, conn, pid, &staged(at(&base, 20.0), Stage::Middle));
    let tag = short.tag.as_ref().expect("a tag");
    assert_eq!((tag.text.as_str(), tag.rule_id.as_str(), tag.source), ("RSV", "stk.reshove.high", TagSource::Read));
    assert_top("reshover at 20bb", &short, &["stk.reshove.high"]);
    let deeper = payload(cache, conn, pid, &staged(at(&base, 30.0), Stage::Middle));
    let tag = deeper.tag.as_ref().expect("a tag");
    assert_eq!((tag.text.as_str(), tag.rule_id.as_str(), tag.source), ("RSV", "stk.reshove.high", TagSource::Read));
}

/// Every declared pair of opposite advice (section 7.2), over every
/// villain and a grid of contexts: never both in the top reads, never both
/// in the reads. The depth pairs are declared at 15–25bb only.
fn check_opposites(conn: &Connection, cache: &mut EngineCache, n: u32, tournament: bool) {
    let always: Vec<(&str, &str)> = PREFLOP_OPPOSITES
        .into_iter()
        .chain(POSTFLOP_OPPOSITES)
        .chain(H2H_OPPOSITES)
        .chain(SHOWDOWN_OPPOSITES)
        .chain(TOURNAMENT_OPPOSITES)
        .chain(REFINED_OPPOSITES)
        .collect();
    let stages: &[Option<Stage>] = if tournament { &[None, Some(Stage::Early), Some(Stage::Late)] } else { &[None] };
    let bounties: &[Option<(f64, bool)>] = if tournament { &[None, Some((3.0, true)), Some((1.0, false))] } else { &[None] };
    let mut checked = 0;
    for (name, pid, base) in villains(conn) {
        for eff in [12.0, 20.0, 30.0, 100.0, 200.0] {
            for distance in [None, Some(1), Some(n / 2), Some(n - 1)] {
                for stage in stages {
                    for b in bounties {
                        let mut ctx = at(&base, eff);
                        ctx.seat = distance.map(|d| seat(d, n));
                        ctx.stage = *stage;
                        if let Some((ratio, covers)) = b {
                            ctx = bounty(ctx, *ratio, *covers);
                        }
                        let p = payload(cache, conn, pid, &ctx);
                        // Section 18: the `stk.reshove.high` pairs hold through jam depth (40bb).
                        let depth: Vec<(&str, &str)> = DEPTH_OPPOSITES
                            .into_iter()
                            .filter(|(s, _)| (eff > 15.0 && eff <= 25.0) || (eff > 15.0 && eff <= 40.0 && *s == "stk.reshove.high"))
                            .collect();
                        for (a, b) in always.iter().chain(&depth) {
                            let has = |reads: &[EngineRuleResult], id: &str| reads.iter().any(|r| r.rule_id == id);
                            assert!(!(has(&p.top_reads, a) && has(&p.top_reads, b)), "{name} {ctx:?}: {a} and {b} in the top reads");
                            assert!(!(has(&p.reads, a) && has(&p.reads, b)), "{name} {ctx:?}: {a} and {b} in the reads");
                        }
                        // The payload's order is section 7's, whatever order
                        // the reads come in (tie-break determinism).
                        let mut reversed = p.reads.clone();
                        reversed.reverse();
                        assert_eq!(rank(reversed), p.reads, "{name} {ctx:?}: ranking depends on input order");
                        assert_eq!(p.top_reads[..], p.reads[..p.top_reads.len()]);
                        checked += 1;
                    }
                }
            }
        }
    }
    assert!(checked >= 200, "contexts checked: {checked}");
}

// ------------------------------------------------------------------ tests

#[test]
fn cash_villains_top_reads_follow_seat_zoom_and_stack_depth() {
    let tmp = tempfile::tempdir().expect("temp dir");
    let conn = corpus(tmp.path(), "cash");
    let mut cache = EngineCache::new();
    // A short-stack 3-bettor who also 4-bets: on the hero's left his 3-bets
    // of the hero's opens lead, on the right his 4-bets of the hero's 3-bets.
    check_seat(&conn, &mut cache, "TwentyBigBlinds", 6, ("pf.3bet.high_ip", "pf.4bet.high"), true, "pf.3bet.high_ip");
    check_zoom(&conn, &mut cache);
    check_depth(&conn, &mut cache);
    check_opposites(&conn, &mut cache, 6, false);
}

#[test]
fn mtt_villains_top_reads_follow_seat_stage_and_bounty() {
    let tmp = tempfile::tempdir().expect("temp dir");
    let conn = corpus(tmp.path(), "mtt");
    let mut cache = EngineCache::new();
    // A nit: on the hero's right his tight early opens lead (fold to them
    // light, steal behind him); on the left his blind folds to steals climb
    // above them (section 18: TripleBarrelTom's in-position 3-bets, .098 over
    // 246, no longer fire the 3-bet read once recency counts each stat's own
    // opportunities).
    check_seat(&conn, &mut cache, "RockSolidRui", 9, ("pf.fold_to_steal.high", "pf.rfi.tight_early"), false, "pf.rfi.tight_early");
    check_stage(&conn, &mut cache);
    check_bounty(&conn, &mut cache);
    check_chip_tag(&conn, &mut cache);
    check_opposites(&conn, &mut cache, 9, true);
}

/// Two reads whose context-adapted scores tie exactly: the higher
/// confidence first, then the rule id, in every input order.
#[test]
fn context_ranking_tie_break_is_deterministic() {
    let make = |id: &str, deviation: f64, confidence: f64, weight: f64, multiplier: f64| EngineRuleResult {
        rule_id: id.to_string(),
        category: RuleCategory::Exploit,
        observation: String::new(),
        advice: String::new(),
        confidence_pct: Some((100.0 * confidence).round() as u8),
        confidence_tier: ConfidenceTier::High,
        evidence: Vec::new(),
        sample: None,
        scenario_id: rule_def(id).scenario.to_string(),
        family: rule_def(id).family,
        tag: rule_def(id).tag.map(str::to_string),
        score: score(deviation, confidence, weight, multiplier),
        deviation,
        confidence,
        weight,
        multiplier,
        adapted_by: Vec::new(),
    };
    // 2.0 × 0.5 × 1 × 1.25 = 1.25 × 0.8 × 1.25 × 1 = 1.0 × 0.5 × 1 × 2.5:
    // equal scores, the h2h read surer than the two others.
    let a = make("pf.cold_call.high", 2.0, 0.5, 1.0, 1.25);
    let b = make("h2h.steal_vs_hero.high", 1.25, 0.8, 1.25, 1.0);
    let c = make("pf.3bet.high_ip", 1.0, 0.5, 1.0, 2.5);
    assert!((a.score - b.score).abs() < 1e-12 && (a.score - c.score).abs() < 1e-12);
    let expected = ["h2h.steal_vs_hero.high", "pf.3bet.high_ip", "pf.cold_call.high"];
    for order in [[0, 1, 2], [2, 1, 0], [1, 2, 0], [2, 0, 1]] {
        let reads: Vec<EngineRuleResult> = order.iter().map(|i| [&a, &b, &c][*i].clone()).collect();
        let ranked = rank_reads(reads, None);
        assert_eq!(ranked.reads.iter().map(|r| r.rule_id.as_str()).collect::<Vec<_>>(), expected);
        assert_eq!(ranked.top_reads.len(), 2);
    }
    // No table scope: every context factor is 1.
    for def in velora_poker_lib::engine::RULES {
        assert_eq!(context_multiplier(def, None), 1.0, "{}", def.id);
        assert!(def.family != Family::H2h || def.seat.is_none(), "{}", def.id);
    }
}


